 "content": "def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    # The 2 marks the apex of a symmetric descending V.
    for r in range(min(center, n - 1 - center) + 1):
        out[r][center-r] = 2
        out[r][center+r] = 2
    # Fill the lower field with diagonal 1-stripes, spaced four cells apart.
    # (Rule will be refined from further demonstrations.)
    for r in range(n):
        for c in range(n):
            if (c-r-2) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out
